    console.log('\n📚 BEHAVIOR ENTITY INFO (painting_rot):');
    console.log('========================================');

    console.log('\n📊 PROPERTY SYSTEM:');
    console.log('32 total int properties (auto-converted to float in Molang):');
    console.log('  • 15 palette properties: crtrlabs_paint:tp0 through tp14 (canonical tiles)');
    console.log('  • 11 index properties: crtrlabs_paint:leaf_idx_f0 through f10 (4-bit palette indices)');
    console.log('  • 6 rotation properties: crtrlabs_paint:rotation_f0 through f5 (2-bit rotations + palette_count)');
    console.log('  • palette_count packed in rotation_f5 at bit offset 8 (NOT a separate property)');

    console.log('\n🔄 ROTATION OPTIMIZATION:');
    console.log('  • Each leaf stores rotation (0-3) = 0°, 90°, 180°, 270°');
    console.log('  • Palette stores canonical tiles only');
    console.log('  • Reduces unique tiles by 60-70% (83,521 → ~25,000-35,000)');
    console.log('  • Atlas size: 512×512 (down from 1024×1024)');

    console.log('\n🎨 TEST PATTERNS:');
    console.log('Available test patterns for default values:');
    console.log('  • checkerboard: Black and white 2×2 checkerboard');
    console.log('  • gradient: Diagonal color gradient using all 16 colors');
    console.log('  • solid: Solid red color');

    console.log('\n🔢 ENCODING SYSTEM:');
    console.log('  • 16×16 pixels → 64 leaves (8×8 grid of 2×2 tiles)');
    console.log('  • Each leaf → canonical tileId + rotation (0-3)');
    console.log('  • Build palette: top 15 most-frequent canonical tileIds');
    console.log('  • Pack leaf indices: 6 nibbles per float (4 bits each)');
    console.log('  • Pack rotations: 12 per float (2 bits each) + palette_count in last float');
    console.log('  • 24-bit safe: all values ≤ 16,777,215');

    console.log('\n📦 ROTATION_F5 SPECIAL PACKING:');
    console.log('  • Bits 0-1:   leaf 60 rotation');
    console.log('  • Bits 2-3:   leaf 61 rotation');
